//! Prospective high-throughput context API/protocol adapter.
//!
//! Atlas feature: `AFA-brain-P03-F23`. The adapter provides bounded, replay-bound
//! protocol semantics for context batches; transport remains application-owned.

use bioprism_foundation::{AutonomyTier, CapabilityManifest, Determinism, Effect, EvidenceReference, EvidenceState, ResearchSurface, TypedPort, TypedResearchArtifact, PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;

pub const FEATURE_ID: &str = "AFA-brain-P03-F23";
pub const CONTRACT_VERSION: &str = "brain-throughput-context-protocol-adapter/1.0";
pub const PROTOCOL_VERSION: &str = "aurora-research-context-throughput/1.0";
pub const ROUTE: &str = "/v1/research/context/throughput/compile";
pub const METHOD: &str = "POST";
pub const RESPONSE_SCHEMA: &str = "ThroughputContextProtocolResponse1@1";

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ThroughputContextProtocolJob { pub job_id: String, pub context_digest: ContentHash, pub section_digest: ContentHash, pub replay_identity: ContentHash, pub state: EvidenceState, pub ready: bool, pub cost_units: u32, pub raw_data_local: bool, pub boundary: String }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ThroughputContextProtocolRequest { pub request_id: String, pub batch_id: String, pub partition: String, pub jobs: Vec<ThroughputContextProtocolJob>, pub max_concurrency: u16, pub budget_units: u32, pub protocol_version: String, pub method: String, pub route: String, pub content_type: String, pub idempotency_key: String, pub response_schema: String, pub replay_identity: ContentHash, pub policy_allow: bool, pub protected_closure: bool, pub raw_data_local: bool, pub boundary: String }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ThroughputContextProtocolReceipt { pub schema_version: String, pub contract_version: String, pub feature_id: String, pub request_id: String, pub protocol_version: String, pub method: String, pub route: String, pub content_type: String, pub idempotency_key: String, pub response_schema: String, pub status_code: u16, pub disposition: String, pub batch_id: String, pub partition: String, pub candidate_order: Vec<String>, pub admitted_order: Vec<String>, pub blocked_order: Vec<String>, pub unknown_order: Vec<String>, pub checkpoint_seq: u64, pub queue_digest: ContentHash, pub context_digest: ContentHash, pub section_digest: ContentHash, pub request_digest: ContentHash, pub response_digest: ContentHash, pub replay_identity: ContentHash, pub omissions: Vec<String>, pub uncertainty: Vec<String>, pub negative_evidence: Vec<String>, pub effect_receipts: Vec<String>, pub artifact: TypedResearchArtifact, pub raw_data_local: bool, pub boundary: String }
#[derive(Debug, Error, PartialEq, Eq)]
pub enum ThroughputContextProtocolError { #[error("invalid throughput context protocol request: {0}")] Invalid(String), #[error("throughput context protocol artifact failed: {0}")] Artifact(String) }

impl ThroughputContextProtocolReceipt { pub fn validate(&self) -> Result<(), ThroughputContextProtocolError> { if self.schema_version != RESEARCH_CONTRACT_SCHEMA_VERSION || self.contract_version != CONTRACT_VERSION || self.feature_id != FEATURE_ID || self.protocol_version != PROTOCOL_VERSION || self.method != METHOD || self.route != ROUTE || self.response_schema != RESPONSE_SCHEMA || self.boundary != PRECLINICAL_BOUNDARY || !self.raw_data_local || self.request_id.trim().is_empty() || self.content_type != "application/json" || self.idempotency_key.trim().is_empty() || self.batch_id.trim().is_empty() || self.partition.trim().is_empty() || self.candidate_order.is_empty() || self.effect_receipts.is_empty() || !matches!(self.disposition.as_str(), "ready"|"partial"|"unknown"|"blocked") { return Err(ThroughputContextProtocolError::Invalid("throughput context protocol identity, route, queue, idempotency, locality, or effects are incomplete".into())); } if self.admitted_order.iter().chain(self.blocked_order.iter()).chain(self.unknown_order.iter()).any(|id| !self.candidate_order.contains(id)) { return Err(ThroughputContextProtocolError::Invalid("throughput context protocol state is not covered by candidates".into())); } for values in [&self.candidate_order,&self.admitted_order,&self.blocked_order,&self.unknown_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts] { if values.windows(2).any(|p| p[0]>=p[1]) { return Err(ThroughputContextProtocolError::Invalid("throughput context protocol ordering is not canonical".into())); } } if !matches!(self.status_code,200|202|206|403|422) { return Err(ThroughputContextProtocolError::Invalid("throughput context protocol status code is invalid".into())); } for d in [&self.queue_digest,&self.context_digest,&self.section_digest,&self.request_digest,&self.response_digest,&self.replay_identity] { if d.as_str().len()!=64 { return Err(ThroughputContextProtocolError::Invalid("throughput context protocol digest is invalid".into())); } } if self.effect_receipts.iter().any(|e| !e.starts_with("protocol:local-throughput-context-response:") && e!="block:unsafe-release") { return Err(ThroughputContextProtocolError::Invalid("throughput context protocol effect is outside local response gate".into())); } self.artifact.validate_metadata().map_err(|e| ThroughputContextProtocolError::Artifact(e.to_string())) } pub fn digest(&self)->Result<ContentHash,ThroughputContextProtocolError>{ self.validate()?; let value=serde_json::to_value(self).map_err(|e|ThroughputContextProtocolError::Artifact(e.to_string()))?; ContentHash::of_value(&value).map_err(|e|ThroughputContextProtocolError::Artifact(e.to_string())) } }

pub fn throughput_context_protocol_manifest() -> CapabilityManifest { CapabilityManifest { schema_version: RESEARCH_CONTRACT_SCHEMA_VERSION.into(), capability_id: FEATURE_ID.into(), version: CONTRACT_VERSION.into(), owner_crate:"brain".into(), consumers:["throughput context API gateway".into(),"platform reliability engineer".into()].into(), behavior:"maps a bounded context batch to a canonical queue/checkpoint protocol response with capacity and evidence omissions".into(), value:"provides stable high-throughput Decision-Section protocol semantics without silent drops or raw-data export".into(), inputs:vec![TypedPort{name:"throughput_context_protocol_request".into(),schema:"ThroughputContextProtocolRequest1@1".into(),required:true}], outputs:vec![TypedPort{name:"throughput_context_protocol_response".into(),schema:RESPONSE_SCHEMA.into(),required:true}], effects:[Effect::ReadLocalData,Effect::ExecuteLocalComputation,Effect::WriteLocalArtifact].into(), permissions:["protocol:local-throughput-context-response".into()].into(), determinism:Determinism::ByteStable, evidence:vec![EvidenceReference{source_id:"cwl-v1.2".into(),state:EvidenceState::Supported,locator:Some("https://www.commonwl.org/specification/".into())}], authority_requirements:Vec::new(), autonomy_tier:AutonomyTier::A0, surfaces:[ResearchSurface::Ui,ResearchSurface::Api,ResearchSurface::Sdk,ResearchSurface::Cli,ResearchSurface::McpTool,ResearchSurface::Operator].into(), boundary:PRECLINICAL_BOUNDARY.into() } }

pub fn serve_throughput_context_protocol(request:&ThroughputContextProtocolRequest)->Result<ThroughputContextProtocolReceipt,ThroughputContextProtocolError>{ if request.protocol_version!=PROTOCOL_VERSION||request.method!=METHOD||request.route!=ROUTE||request.content_type!="application/json"||request.idempotency_key.trim().is_empty()||request.response_schema!=RESPONSE_SCHEMA||request.boundary!=PRECLINICAL_BOUNDARY||request.request_id.trim().is_empty()||request.batch_id.trim().is_empty()||request.partition.trim().is_empty()||request.jobs.is_empty()||request.max_concurrency==0||request.budget_units==0||request.replay_identity.as_str().len()!=64{return Err(ThroughputContextProtocolError::Invalid("throughput context protocol identity, route, queue, budget, replay, or boundary is invalid".into()));} let mut jobs=request.jobs.clone(); jobs.sort_by(|a,b|a.job_id.cmp(&b.job_id)); let candidate=jobs.iter().map(|j|j.job_id.clone()).collect::<Vec<_>>(); if candidate.windows(2).any(|p|p[0]==p[1])||candidate.iter().any(|v|v.trim().is_empty()){return Err(ThroughputContextProtocolError::Invalid("throughput context protocol job identifiers must be unique and non-empty".into()));} let mut admitted=BTreeSet::new();let mut blocked=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omissions=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();let open=request.policy_allow&&request.protected_closure&&request.raw_data_local;let mut consumed=0u32;for job in &jobs{if !open||!job.raw_data_local||job.boundary!=PRECLINICAL_BOUNDARY{blocked.insert(job.job_id.clone());omissions.insert(format!("job:{}:policy-locality-blocked",job.job_id));}else if job.replay_identity!=request.replay_identity{unknown.insert(job.job_id.clone());uncertainty.insert(format!("job:{}:replay-mismatch",job.job_id));}else if !job.ready{unknown.insert(job.job_id.clone());uncertainty.insert(format!("job:{}:not-ready",job.job_id));}else if matches!(job.state,EvidenceState::Speculative|EvidenceState::Unknown){unknown.insert(job.job_id.clone());uncertainty.insert(format!("job:{}:evidence-uncertain",job.job_id));}else if matches!(job.state,EvidenceState::Contradicted){blocked.insert(job.job_id.clone());negative.insert(format!("job:{}:contradicted",job.job_id));}else if admitted.len()>=request.max_concurrency as usize{unknown.insert(job.job_id.clone());uncertainty.insert(format!("job:{}:concurrency-window",job.job_id));}else if consumed.saturating_add(job.cost_units)>request.budget_units{blocked.insert(job.job_id.clone());omissions.insert(format!("job:{}:budget-exhausted",job.job_id));}else{admitted.insert(job.job_id.clone());consumed+=job.cost_units;}} let disposition=if !open{"blocked"}else if admitted.len()==candidate.len(){"ready"}else if !unknown.is_empty(){"unknown"}else{"partial"};let status=if !open{403}else if disposition=="ready"{200}else if disposition=="partial"{206}else{202};if !request.policy_allow{omissions.insert("protocol:policy-denied".into());}if !request.protected_closure{omissions.insert("protocol:protected-closure-incomplete".into());}if !request.raw_data_local{omissions.insert("protocol:raw-data-locality-failed".into());}let queue_digest=ContentHash::of_value(&json!({"candidate_order":candidate,"admitted_order":admitted,"blocked_order":blocked,"unknown_order":unknown,"max_concurrency":request.max_concurrency,"budget_units":request.budget_units,"consumed":consumed,"replay_identity":request.replay_identity})).map_err(|e|ThroughputContextProtocolError::Artifact(e.to_string()))?;let context_digest=ContentHash::of_value(&json!({"batch_id":request.batch_id,"queue_digest":queue_digest,"replay_identity":request.replay_identity})).map_err(|e|ThroughputContextProtocolError::Artifact(e.to_string()))?;let section_digest=ContentHash::of_value(&json!({"partition":request.partition,"context_digest":context_digest,"admitted_order":admitted})).map_err(|e|ThroughputContextProtocolError::Artifact(e.to_string()))?;let request_value=serde_json::to_value(request).map_err(|e|ThroughputContextProtocolError::Artifact(e.to_string()))?;let request_digest=ContentHash::of_value(&request_value).map_err(|e|ThroughputContextProtocolError::Artifact(e.to_string()))?;let response_digest=ContentHash::of_value(&json!({"protocol_version":PROTOCOL_VERSION,"route":ROUTE,"request_id":request.request_id,"status_code":status,"disposition":disposition,"queue_digest":queue_digest,"replay_identity":request.replay_identity})).map_err(|e|ThroughputContextProtocolError::Artifact(e.to_string()))?;let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":request.request_id,"protocol_version":PROTOCOL_VERSION,"method":METHOD,"route":ROUTE,"response_schema":RESPONSE_SCHEMA,"status_code":status,"disposition":disposition,"batch_id":request.batch_id,"partition":request.partition,"queue_digest":queue_digest,"context_digest":context_digest,"section_digest":section_digest,"request_digest":request_digest,"response_digest":response_digest,"replay_identity":request.replay_identity,"boundary":PRECLINICAL_BOUNDARY});let artifact=TypedResearchArtifact::from_payload(format!("brain-throughput-context-protocol:{}",request.request_id),"application/vnd.aurora.throughput-context-protocol-response+json",&payload,Vec::new(),Vec::new()).map_err(|e|ThroughputContextProtocolError::Artifact(e.to_string()))?;let receipt=ThroughputContextProtocolReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:CONTRACT_VERSION.into(),feature_id:FEATURE_ID.into(),request_id:request.request_id.clone(),protocol_version:PROTOCOL_VERSION.into(),method:METHOD.into(),route:ROUTE.into(),content_type:"application/json".into(),idempotency_key:request.idempotency_key.clone(),response_schema:RESPONSE_SCHEMA.into(),status_code:status,disposition:disposition.into(),batch_id:request.batch_id.clone(),partition:request.partition.clone(),candidate_order:candidate,admitted_order:admitted.into_iter().collect(),blocked_order:blocked.into_iter().collect(),unknown_order:unknown.into_iter().collect(),checkpoint_seq:jobs.len() as u64,queue_digest,context_digest,section_digest,request_digest,response_digest,replay_identity:request.replay_identity.clone(),omissions:omissions.into_iter().collect(),uncertainty:uncertainty.into_iter().collect(),negative_evidence:negative.into_iter().collect(),effect_receipts:if open{vec![format!("protocol:local-throughput-context-response:{}",request.idempotency_key)]}else{vec!["block:unsafe-release".into()]},artifact,raw_data_local:true,boundary:PRECLINICAL_BOUNDARY.into()};receipt.validate()?;Ok(receipt)}

#[cfg(test)] mod tests { use super::*; fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())} fn request(state:EvidenceState)->ThroughputContextProtocolRequest{let r=h("throughput-context-protocol-replay");let jobs=vec![ThroughputContextProtocolJob{job_id:"job:a".into(),context_digest:r.clone(),section_digest:r.clone(),replay_identity:r.clone(),state:state.clone(),ready:true,cost_units:1,raw_data_local:true,boundary:PRECLINICAL_BOUNDARY.into()},ThroughputContextProtocolJob{job_id:"job:b".into(),context_digest:r.clone(),section_digest:r.clone(),replay_identity:r.clone(),state,ready:true,cost_units:1,raw_data_local:true,boundary:PRECLINICAL_BOUNDARY.into()}];ThroughputContextProtocolRequest{request_id:"request:throughput-context".into(),batch_id:"batch:1".into(),partition:"partition:0".into(),jobs,max_concurrency:2,budget_units:2,protocol_version:PROTOCOL_VERSION.into(),method:METHOD.into(),route:ROUTE.into(),content_type:"application/json".into(),idempotency_key:"idem:throughput-context".into(),response_schema:RESPONSE_SCHEMA.into(),replay_identity:r,policy_allow:true,protected_closure:true,raw_data_local:true,boundary:PRECLINICAL_BOUNDARY.into()}} #[test] fn manifest_is_a0_local(){assert_eq!(throughput_context_protocol_manifest().autonomy_tier,AutonomyTier::A0)} #[test] fn ready_returns_200(){assert_eq!(serve_throughput_context_protocol(&request(EvidenceState::Supported)).unwrap().status_code,200)} #[test] fn unknown_returns_202(){assert_eq!(serve_throughput_context_protocol(&request(EvidenceState::Unknown)).unwrap().status_code,202)} #[test] fn concurrency_is_unknown(){let mut x=request(EvidenceState::Supported);x.max_concurrency=1;let r=serve_throughput_context_protocol(&x).unwrap();assert!(r.unknown_order.len()>0)} #[test] fn policy_returns_403(){let mut x=request(EvidenceState::Supported);x.policy_allow=false;let r=serve_throughput_context_protocol(&x).unwrap();assert_eq!(r.status_code,403)} #[test] fn digest_is_stable(){let r=serve_throughput_context_protocol(&request(EvidenceState::Supported)).unwrap();assert_eq!(r.digest().unwrap(),r.digest().unwrap())} }
